const opportunityLink=(id,tab='overview')=>`#opportunity/${id}/${tab}`;
function homeView(){const tasks=[['t1','补齐「需求判断」的个人回答','澄川智能 · AI 产品经理','今天','继续准备','opportunity/cc/interview'],['t2','核对网申中的项目经历与联系方式','观澜数据 · 数据产品经理','今天','核对字段','opportunity/gl/application'],['t3','确认一条项目事实的表述边界','校园知识库问答 · 结果与指标','待确认','查看资料','profile']];return `<div class="page-heading"><div><div class="eyebrow">11 月 17 日，星期二</div><h1>今日工作台</h1><p>知夏，先把明天的一面准备好。</p></div><div class="heading-aside"><strong>求职的每一步，都有据可循。</strong>从目标机会出发，完成今天最重要的事</div></div><section class="focus-panel" aria-labelledby="focus-title"><div><div class="focus-kicker">${icon('clock','small-icon')} 明天 14:00 · 业务一面<span class="badge blue">当前重点</span></div><h2 id="focus-title">澄川智能 · AI 产品经理</h2><p>已有 5 道相关问题。需求判断与评估方法，还需要结合你的项目再练一次。</p></div><div class="focus-actions"><a class="button primary" href="${opportunityLink('cc','interview')}">继续面试准备 ${icon('arrow')}</a><span class="small muted">预计 20 分钟 · 从上次的位置继续</span></div></section><div class="home-grid"><section class="panel"><div class="panel-head"><h2>今天要推进的事 <span class="small muted" style="font-weight:400;margin-left:7px">${tasks.filter(t=>!state.tasksDone.includes(t[0])).length} 项待完成</span></h2><span class="small muted">按优先级</span></div><div class="panel-body">${tasks.map(([id,title,sub,date,label,href])=>`<div class="task-row ${state.tasksDone.includes(id)?'done':''}">${action('toggle-task',state.tasksDone.includes(id)?icon('check'):'','task-check '+(state.tasksDone.includes(id)?'checked':''),`data-id="${id}" aria-label="${state.tasksDone.includes(id)?'恢复':'完成'}：${title}" aria-pressed="${state.tasksDone.includes(id)}"`)}<div class="task-body"><div class="task-title">${title}</div><p>${sub}<span style="margin:0 7px;color:#b1b8c3">·</span>${date}</p></div><a class="task-action" href="#${href}">${label} <span aria-hidden="true">→</span></a></div>`).join('')}</div></section><aside class="home-secondary"><section class="panel"><div class="panel-head"><h2>本周安排</h2>${icon('calendar')}</div><div class="panel-body"><div class="schedule-item"><div class="date-block">周三<strong>18</strong></div><div><p>澄川智能 · 业务一面</p><small>14:00 – 14:45 · 线上面试</small><a href="${opportunityLink('cc','progress')}" class="text-button small">查看面试安排</a></div></div><div class="schedule-item"><div class="date-block">周五<strong>20</strong></div><div><p>观澜数据 · 申请计划</p><small>18:00 前 · 自定截止时间</small></div></div></div></section><div class="note-panel"><h3>还没有具体职位，也可以开始。</h3><p>按公司与岗位搜索面经，把有价值的问题保存到一个准备目标中。</p>${action('search-interviews','搜索相关面经 '+icon('arrow','small-icon'),'text-button')}</div></aside></div><section class="recent-section"><div class="section-title"><h2>近期目标机会</h2><a href="#opportunities" class="text-button">查看全部 ${icon('chevron','small-icon')}</a></div><div class="panel">${opportunityTable(state.opportunities.slice(0,2))}</div></section>`}
function opportunityTable(items){return `<table class="data-table"><thead><tr><th>公司 / 岗位</th><th>求职进展</th><th class="hide-small">下一步</th><th class="hide-medium">最近更新</th><th><span class="sr-only">操作</span></th></tr></thead><tbody>${items.map(o=>`<tr><td><div class="company-cell"><span class="company-monogram ${o.id==='gl'?'slate':''}">${esc(o.company[0])}</span><div><strong>${esc(o.company)}</strong><small>${esc(o.role)}</small></div></div></td><td>${statusBadge(o.stage)}</td><td class="hide-small">${esc(o.next)}</td><td class="hide-medium muted">今天</td><td><a class="text-button" href="${opportunityLink(o.id)}">进入 ${icon('chevron','small-icon')}</a></td></tr>`).join('')}</tbody></table>`}
function opportunityRows(){const filtered=state.opportunities.filter(o=>(ui.filter==='全部'||o.stage===ui.filter)&&`${esc(o.company)}${esc(o.role)}${o.location}`.toLowerCase().includes(ui.search.toLowerCase()));return filtered.length?filtered.map(o=>`<article class="opportunity-row"><div class="company-cell"><span class="company-monogram ${o.id==='gl'?'slate':''}">${esc(o.company[0])}</span><div><h3>${esc(o.company)} · ${esc(o.role)}</h3><small>${esc(o.location)}</small></div></div><div class="next-step"><small>${esc(o.next)}</small>${esc(o.action)}</div>${statusBadge(o.stage)}<a class="button sm row-open" href="${opportunityLink(o.id)}">打开机会 ${icon('chevron','small-icon')}</a></article>`).join(''):`<div class="empty-state">${icon('search')}<h3>没有符合条件的目标机会</h3><p>试试其他公司、岗位，或清除当前筛选。</p>${action('clear-filter','清除筛选','button')}</div>`}
function opportunitiesView(){return `<div class="page-heading"><div><div class="eyebrow">围绕一个目标，准备所有下一步</div><h1>面试准备</h1><p>按目标岗位整理面经、项目回答与练习。</p></div>${action('create-opportunity',icon('plus')+' 添加目标','button')}</div><div class="toolbar"><div class="search-field">${icon('search')}<label class="sr-only" for="opportunity-search">搜索公司或岗位</label><input id="opportunity-search" type="search" value="${esc(ui.search)}" placeholder="搜索公司、岗位或城市"></div><div class="filter-tabs" aria-label="按进展筛选">${['全部','准备中','准备投递','面试中'].map(f=>action('filter',f,'filter-tab '+(ui.filter===f?'active':''),`data-filter="${f}" aria-pressed="${ui.filter===f}"`)).join('')}</div></div><div class="opportunity-list" id="opportunity-list">${opportunityRows()}</div><div class="tip-line">${icon('info','small-icon')}还没拿到 JD？只填公司与岗位，也能创建一个准备目标。</div>`}
function opportunityView(){const o=opp(),r=route();return `${state.mode==='mentor'?`<div class="context-bar"><span><strong>正在查看 ${o.id==='zhou'?'周予安':'林知夏'} 的机会</strong> <span class="muted">· 已授权导师查看的示例空间</span></span><a href="#students" class="text-button">返回学员列表</a></div>`:''}<div class="opportunity-title-row"><div class="opportunity-heading"><span class="company-monogram large ${o.id==='gl'?'slate':''}">${esc(o.company[0])}</span><div><div class="inline wrap"><h1>${esc(o.company)}</h1>${statusBadge(o.stage)}</div><div class="opportunity-meta"><span>${esc(o.role)}</span><span>·</span><span>${esc(o.location)}</span></div></div></div>${action('edit-opportunity',icon('edit','small-icon')+' 编辑目标','button')}</div><nav class="tabs" aria-label="机会工作空间">${[['overview','概览'],['application','投递准备'],['interview','面试准备'],['progress','进展']].map(([tab,label])=>`<a href="${opportunityLink(o.id,tab)}" class="${r.tab===tab?'active':''}" ${r.tab===tab?'aria-current="page"':''}>${label}</a>`).join('')}</nav>${({overview:overviewView,application:applicationView,interview:interviewView,progress:progressView}[r.tab]||overviewView)(o)}`}
function overviewView(o){return `<div class="opportunity-overview"><div class="stack"><section class="panel"><div class="panel-head"><h2>下一步，${o.id==='cc'?'把项目讲得更具体':'准备一份有针对性的申请'}</h2><span class="badge blue">${o.id==='cc'?'明天一面':'当前重点'}</span></div><div class="panel-body"><p class="medium">${esc(o.action)}</p><p class="small muted mt8">${o.id==='cc'?'从需求判断开始，说明证据、个人贡献与尚未验证的边界。':'先核对你的真实经历，再根据岗位要求选择合适的项目表述。'}</p><a class="button primary mt16" href="${opportunityLink(o.id,o.id==='cc'?'interview':'application')}">${o.id==='cc'?'继续面试准备':'开始投递准备'} ${icon('arrow')}</a></div></section><section class="panel"><div class="panel-head"><h2>这个机会的准备路径</h2><span class="small muted">资料始终在同一处</span></div><div class="panel-body"><ol class="step-list"><li><span class="step-number">${icon('check','small-icon')}</span><div class="spacer"><h3>理解岗位</h3><p>${o.jd?'已记录岗位要求与能力重点':'尚未关联 JD；可以先基于公司与岗位准备'}</p></div>${action('show-jd','查看','text-button')}</li><li><span class="step-number ${o.id!=='cc'?'current':''}">02</span><div class="spacer"><h3>准备投递材料</h3><p>项目摘要、BOSS 招呼、网申字段，统一引用个人事实</p></div><a class="text-button" href="${opportunityLink(o.id,'application')}">打开</a></li><li><span class="step-number ${o.id==='cc'?'current':''}">03</span><div class="spacer"><h3>准备与练习</h3><p>5 道示例面经问题 · 原题、意图与个人回答</p></div><a class="text-button" href="${opportunityLink(o.id,'interview')}">打开</a></li><li><span class="step-number">04</span><div class="spacer"><h3>记录进展与复盘</h3><p>${esc(o.next)}</p></div><a class="text-button" href="${opportunityLink(o.id,'progress')}">查看</a></li></ol></div></section></div><aside class="stack"><section class="panel panel-pad"><h2 style="font-size:15px">岗位关注什么</h2>${o.jd?`<ul class="jd-list"><li>从用户问题识别产品机会</li><li>理解 AI 应用与评估方法</li><li>推动跨职能协作与迭代</li><li>用真实证据解释决策</li></ul>`:`<p class="small muted mt12">当前只有公司与岗位目标。补充 JD 后，可进一步核对岗位匹配点。</p>`}${action('show-jd',o.jd?'查看示例 JD':'补充 JD','text-button mt12')}</section><section class="panel panel-pad"><h2 style="font-size:15px">已关联的个人资料</h2><div class="inline mt16">${icon('file')}<div><strong class="small">${projectName()}</strong><p class="small muted">4 条项目事实 · ${currentFacts().filter(f=>f.confirmed).length} 条已确认</p></div></div><a href="${profileHref()}" class="text-button mt16">核对项目事实 ${icon('arrow','small-icon')}</a></section></aside></div>`}
function interviewView(o){const q=currentQuestion();return `<div class="interview-toolbar"><div><h2>把别人的面经，变成你的回答</h2><p class="small muted mt8">先看原题，再用已确认的项目事实组织答案。</p></div>${action('search-interviews',icon('search','small-icon')+' 搜索面经','button')}</div><div class="interview-layout"><aside><div class="question-panel"><div class="question-header between"><span>准备问题</span><span class="small muted">5 道</span></div><div class="question-list">${questions.map((q,i)=>action('question',`<span>${esc(q.title)}</span><small><span>${q.category}</span><span>${workspace().savedQuestions.includes(i)?'已保存':i<2?'优先准备':'待练习'}</span></small>`,'question-item '+(ui.question===i?'active':''),`data-index="${i}" aria-pressed="${ui.question===i}"`)).join('')}</div><div class="question-footer">${action('search-interviews',icon('plus','small-icon')+' 添加相关问题','text-button')}</div></div><div class="sources-note"><strong>来源与可信度</strong>这里展示的是虚构「示例面经」，仅用于演示信息组织。原文不会被个人回答覆盖。</div></aside><div><section class="source-panel"><div class="source-meta"><span class="badge">原题</span><span>${q.source}</span><span>·</span><span>${q.meta}</span></div><h2 class="source-question">${q.title}</h2><button class="text-button small mt8" data-action="toggle-original" aria-expanded="${ui.originalOpen}">${ui.originalOpen?'收起面经原文':'展开面经原文'} ${icon('down','small-icon')}</button>${ui.originalOpen?`<blockquote class="source-original">${q.original}</blockquote>`:''}<div class="intent-row"><strong>可能考察什么 <span class="badge">AI 推断 · 演示</span></strong>${q.intent}</div><div class="adapted-question"><div class="between"><strong>针对你的改写题</strong><span class="badge ${ui.question===1?'amber':'blue'}">${ui.question===1?'部分适配':'项目适配 · 演示'}</span></div><p>${q.adapted}</p>${ui.question===1?'<div class="adaptation-gap">保留差距：离线评估不等同线上 A/B 测试。仅迁移指标设计思路；实验分组、因果判断和线上结果仍需补学，不写成已有经验。</div>':''}</div></section><div class="answer-grid"><section class="answer-panel"><div class="answer-panel-head"><div class="mini-tabs">${action('answer-tab','我的回答',''+(ui.answerTab==='answer'?'active':''),'data-tab="answer" aria-pressed="'+(ui.answerTab==='answer')+'"')}${action('answer-tab','开口练习',''+(ui.answerTab==='practice'?'active':''),'data-tab="practice" aria-pressed="'+(ui.answerTab==='practice')+'"')}</div><span class="badge blue">演示内容</span></div><div class="answer-content">${ui.answerTab==='practice'?practiceContent():`${workspace().answers[ui.question]?`<p style="white-space:pre-line">${esc(workspace().answers[ui.question])}</p>`:q.answer.map(([label,text],i)=>`<div class="answer-part"><label>${label}</label><p>${esc(text)}<a class="evidence-mark" href="${profileHref()}" aria-label="查看对应的项目事实">F${i===0?1:i===1?(ui.question===1||ui.question===3?3:2):4}</a></p></div>`).join('')}<div class="inline wrap mt24">${action('save-answer',(workspace().savedQuestions.includes(ui.question)?icon('check','small-icon')+' 已保存':icon('bookmark','small-icon')+' 保存到准备材料'),'button primary sm')}${action('edit-answer',icon('edit','small-icon')+' 编辑回答','button sm')}</div>`}</div><div class="answer-footer"><span>使用已确认事实；未知结果保留边界。</span><a href="${profileHref()}" class="text-button small">核对资料</a></div></section><aside class="evidence-panel"><h3>我的事实依据</h3><p>回答中的表述，应能回到具体经历。</p>${currentFacts().filter((f,i)=>i===0||i===(ui.question===1||ui.question===3?2:1)).map(f=>`<div class="evidence-card"><div class="between"><span class="small strong">${f.id} · ${f.title}</span><span class="badge ${f.confirmed?'green':'amber'}">${f.confirmed?'已确认':'待确认'}</span></div><p>${esc(f.text)}</p><small>来自：${projectName()}</small></div>`).join('')}<div class="evidence-card"><div class="between"><span class="small strong">F4 · 结果边界</span><span class="badge ${currentFacts()[3].confirmed?'green':'amber'}">${currentFacts()[3].confirmed?'已确认':'待确认'}</span></div><p>${esc(currentFacts()[3].text)}</p></div><div class="caution-note">不可把未验证的线上成效，写成已经取得的结果。</div><a href="${profileHref()}" class="text-button small mt8">查看全部项目事实 ${icon('arrow','small-icon')}</a></aside></div></div></div>`}
function practiceContent(){return `<label for="practice-answer">试着用 90 秒讲清楚</label><p class="small muted">可以先输入你的口述稿。提交后显示基于规则的示例反馈，不进行真实 AI 评分。</p><textarea id="practice-answer" class="practice-input" placeholder="从你真实做过的一件事开始……">${esc(practice().text)}</textarea><div class="between"><span class="small muted" id="practice-count">${practice().text.length} 字</span>${action('practice-feedback','查看示例反馈','button primary sm')}</div>${practice().feedback?`<div class="feedback" role="status"><strong>练习反馈 · 本机演示</strong><p>${practice().text.length<50?'当前回答较短，可以补充一次具体决策：当时有哪些选择，你依据什么做出取舍。':'已经有了可展开的表达。建议先说结论，再补充一个具体动作和它的依据。'}</p><p>${/\d/.test(practice().text)?'你使用了数字。请核对它们是否来自已确认资料，并主动说明样本和评估口径。':'试着加入已确认的访谈人数、问题数或评估集规模，让依据更具体。'}</p><p>下一轮追问：如果再增加 20 位受访者，你的优先级可能如何变化？</p></div>`:''}`}
function applicationView(o){return `<div class="section-title"><div><h2>投递前，把材料和字段一次对齐</h2><p class="small muted mt8">每一次表达，都能回到你的项目事实。</p></div><span class="badge">本机模拟 · 不会发送</span></div>${workspace().confirmedApplication?'<div class="local-banner">已完成一次模拟填写确认。没有提交网申，也没有向招聘方发送消息。</div>':''}<div class="application-layout"><div class="stack"><section class="panel"><div class="panel-head"><h2>岗位专属材料</h2><span class="small muted">${esc(o.company)} · ${esc(o.role)}</span></div><div class="panel-body"><div class="material-item"><span class="file-icon">${icon('file')}</span><div class="material-body"><h3>项目摘要 · 岗位表达版</h3><p>引用 F1–F3 · 保留个人贡献和评估边界</p></div>${action('preview-material','预览','button sm')}</div><div class="material-item"><span class="file-icon">${icon('file')}</span><div class="material-body"><h3>个人简历信息摘要</h3><p>示例资料 · 导出文本后可自行整理到简历</p></div>${action('download-material',icon('download','small-icon')+' 导出','button sm')}</div></div></section><section class="panel"><div class="panel-head"><h2>BOSS 招呼草稿</h2><span class="badge blue">示例生成</span></div><div class="panel-body"><div class="greeting" id="greeting-text">${greeting(o)}</div><div class="between mt16"><span class="small muted">基于岗位 + 已确认项目事实</span>${action('copy-greeting',icon('copy','small-icon')+' 复制招呼','button sm')}</div><p class="field-help">本页使用虚构示例资料。真实求职请从顶部或侧栏进入「BOSS 岗位搜索」，使用你的真实简历生成草稿。</p></div></section><section class="panel"><div class="panel-head"><h2>网申字段核对</h2><span class="small muted">模拟表单 · 4 项</span></div><form class="panel-body" id="application-form"><div class="form-grid"><div><label for="app-name">姓名</label><input id="app-name" name="name" value="${studentName()}" required></div><div><label for="app-email">联系邮箱</label><input id="app-email" name="email" type="email" value="${isZhou()?'zhou.yuan':'lin.zhixia'}@example.com" required><p class="field-help">虚构邮箱，仅用于演示</p></div><div class="field-full"><label for="app-role">申请岗位</label><input id="app-role" name="role" value="${esc(o.role)}" required></div><div class="field-full"><label for="app-project">项目经历摘要</label><textarea id="app-project" name="project" rows="3" required style="min-height:105px">${projectSummary()}</textarea></div></div><div class="between mt16"><span class="small muted">下一步：逐项预览并确认</span><button type="submit" class="button primary">生成模拟填写预览 ${icon('arrow','small-icon')}</button></div></form></section></div><aside class="stack"><section class="panel panel-pad"><h2 style="font-size:15px">投递检查</h2><ul class="checklist mt12"><li><span>岗位与公司</span><span class="badge green">已关联</span></li><li><span>个人贡献</span><span class="badge green">已确认</span></li><li><span>量化事实</span><span class="badge green">可追溯</span></li><li><span>线上效果</span><span class="badge amber">未验证</span></li><li><span>网申字段</span><span class="badge ${workspace().confirmedApplication?'green':'amber'}">${workspace().confirmedApplication?'演示已确认':'待人工确认'}</span></li></ul><a class="text-button mt16" href="${profileHref()}">查看原始资料 ${icon('arrow','small-icon')}</a></section><div class="notice">模拟填写不会打开外部页面。你将先看到每个字段的值，确认后仅在本机记录演示状态。</div></aside></div>`}
function greeting(o){return isZhou()?`您好，我是周予安，关注到贵司的${esc(o.role)}岗位。我曾作为产品助理参与企业指标目录项目，负责需求研究、字段定义与验收清单，关注指标口径和数据来源的一致性。希望进一步了解团队的业务场景，谢谢。`:`您好，我是林知夏，关注到贵司的${esc(o.role)}岗位。我曾负责校园知识库问答项目的用户研究与产品设计，访谈 12 位同学并搭建 80 题离线评估集，重点关注需求取舍和答案可追溯性。希望有机会进一步了解团队正在解决的问题，谢谢。`}
function profileView(){return `<div class="page-heading"><div><div class="eyebrow">所有岗位表达的事实底稿</div><h1>${route().view==='student-profile'?studentName()+'的资料':'我的资料'}</h1><p>确认你真正做过的事，再决定如何表达。</p></div><span class="badge">修改仅保存在本机</span></div><div class="profile-layout"><div class="stack"><section class="panel panel-pad"><div class="profile-summary"><span class="avatar large">${studentName()[0]}</span><div><h2>${studentName()}</h2><p>2027 届 · 产品方向 · 示例求职者</p></div><span class="spacer"></span>${route().view==='student-profile'?'<span class="badge">学员授权示例</span>':action('edit-profile','编辑基本资料','button sm')}</div><div class="form-grid"><div><div class="small muted">目标方向</div><div class="mt8">${esc(isZhou()?'数据产品经理':state.profileDirection||'AI 产品经理 / 数据产品经理')}</div></div><div><div class="small muted">当前阶段</div><div class="mt8">在校 · 寻找全职 / 实习机会</div></div></div></section><section class="panel"><div class="panel-head"><div><h2>${projectName()}</h2><p class="small muted mt8">${isZhou()?'2026.05 – 2026.08 · 实习实践项目 · 产品助理':'2026.03 – 2026.06 · 课程实践项目 · 产品负责人'}</p></div><span class="badge">${currentFacts().filter(f=>f.confirmed).length}/4 已确认</span></div><div class="panel-body">${currentFacts().map(f=>`<div class="fact-row"><span class="fact-id">${f.id}</span><div><h3>${esc(f.title)}</h3><p>${esc(f.text)}</p></div><div class="fact-status"><span class="badge ${f.confirmed?'green':'amber'}">${f.confirmed?'已确认':'待确认'}</span>${action('edit-fact','编辑 / 核对','text-button',`data-id="${f.id}"`)}</div></div>`).join('')}</div></section></div><aside class="stack"><section class="panel panel-pad"><h2 style="font-size:15px">什么是「确认事实」</h2><p class="small muted mt12" style="line-height:1.9">确认代表你核对过表述、数字和个人贡献。它是生成回答的依据，不代表已经被外部验证。</p><hr class="divider"><div class="inline"><span class="badge green">已确认</span><span class="small muted">可用于个人表达</span></div><div class="inline mt12"><span class="badge amber">待确认</span><span class="small muted">保留边界，不补写成绩</span></div></section><section class="panel panel-pad"><h2 style="font-size:15px">这些资料正在用于</h2>${isZhou()?'<a class="target-link" style="padding:16px 0 0" href="#opportunity/zhou/application"><span class="target-dot"></span><div>观澜数据<small>投递准备 · 指标目录项目</small></div></a>':'<a class="target-link" style="padding:16px 0 0" href="#opportunity/cc/interview"><span class="target-dot"></span><div>澄川智能<small>面试回答 · 需求判断 / 效果评估</small></div></a>'}</section><div class="notice">所有人物、项目与数字均为虚构示例。本机保存便于你刷新页面后继续体验。</div></aside></div>`}
function progressView(o){return `<div class="opportunity-overview"><section class="panel"><div class="panel-head"><h2>求职进展</h2>${action('update-progress',icon('plus','small-icon')+' 记录进展','button sm')}</div><div class="panel-body"><div class="timeline">${state.stageHistory.filter(h=>h.id===o.id).slice().reverse().map(h=>`<div class="timeline-item active"><small>刚刚 · 本机记录</small><h3>${esc(h.stage)}</h3><p>${esc(h.note)}</p></div>`).join('')}<div class="timeline-item active"><small>${o.id==='cc'?'11 月 18 日 · 14:00 – 14:45':'11 月 20 日 · 自定计划'}</small><h3>${o.id==='cc'?'业务一面 · 即将开始':'完成申请材料'}</h3><p>${o.id==='cc'?'线上面试。重点准备需求判断、AI 产品评估与项目分工。':'核对字段和联系方式，确认材料后再到招聘平台自行投递。'}</p><a class="text-button mt8" href="${opportunityLink(o.id,o.id==='cc'?'interview':'application')}">继续准备 ${icon('arrow','small-icon')}</a></div><div class="timeline-item"><small>11 月 16 日</small><h3>${o.id==='cc'?'收到一面邀请':'建立投递清单'}</h3><p>已把下一步加入工作台。</p></div><div class="timeline-item"><small>11 月 14 日</small><h3>创建目标机会</h3><p>记录公司、岗位与准备方向，关联校园知识库问答项目。</p></div></div></div></section><aside class="stack"><section class="panel panel-pad"><h2 style="font-size:15px">下一次行动</h2><p class="medium strong mt16">${esc(o.next)}</p><p class="small muted mt8">${esc(o.action)}</p>${action('update-progress','调整记录','button sm mt16')}</section><div class="notice">这里记录你手动更新的求职进展。演示中不会同步日历、发送提醒或自动查询招聘状态。</div></aside></div>`}
function openModal(title,subtitle,body,footer='',wide=false){
  syncNativeSurface(true);
  const dialog=$('#modal');dialog.className=wide?'wide':'';
  dialog.innerHTML=`<div class="modal-header"><div><h2 id="modal-title">${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div>${action('close-modal',icon('close'),'icon-button','aria-label="关闭对话框"')}</div><div class="modal-body">${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}`;
  if(!dialog.open)dialog.showModal();bindForms();
}
function closeModal(){$('#modal').close()}
function newTaskModal(type='search'){ui.newType=type;const tabs=`<div class="modal-tabs">${[['search','搜索面经'],['opportunity','新建机会'],['application','准备投递']].map(([id,label])=>action('new-type',label,'modal-tab '+(ui.newType===id?'active':''),`data-type="${id}" aria-pressed="${ui.newType===id}"`)).join('')}</div>`;let body='';if(type==='search'){body=`<form id="search-form"><div class="form-grid"><div><label for="search-company">公司</label><input id="search-company" name="company" placeholder="如：澄川智能" value="${esc(route().view==='opportunity'?opp().company:'澄川智能')}"></div><div><label for="search-role">岗位 / 关键词</label><input id="search-role" name="role" placeholder="如：AI 产品经理" value="AI 产品"></div></div><p class="field-help">不需要 JD。当前搜索仅匹配内置「示例面经」。</p><button class="button primary mt16" type="submit">${icon('search','small-icon')} 搜索示例面经</button></form><div id="interview-results"></div>`}else if(type==='opportunity'){body=`<form id="create-opportunity-form"><div class="form-grid"><div><label for="new-company">目标公司 <span class="accent">*</span></label><input id="new-company" name="company" required placeholder="输入公司名称"></div><div><label for="new-role">目标岗位 <span class="accent">*</span></label><input id="new-role" name="role" required placeholder="输入岗位名称"></div><div class="field-full"><label for="new-jd">岗位描述（选填）</label><textarea id="new-jd" name="jd" rows="4" placeholder="有 JD 可以粘贴；没有也能先创建准备目标。"></textarea></div></div><div class="notice mt16">先创建一个独立机会，面经、投递材料和后续进展都保存在这里。</div><button class="button primary mt16" type="submit">创建目标机会 ${icon('arrow','small-icon')}</button></form>`}else{body=`<form id="choose-application-form"><label for="application-opportunity">先选择这次投递的目标</label><select id="application-opportunity">${state.opportunities.map(o=>`<option value="${esc(o.id)}">${esc(o.company)} · ${esc(o.role)}</option>`).join('')}</select><div class="notice mt16">将打开该机会的材料、BOSS 招呼与网申字段。所有发送与填表均为演示。</div><button class="button primary mt16" type="submit">进入投递准备 ${icon('arrow','small-icon')}</button></form>`}openModal('新建任务','从眼前要完成的事开始，资料会归到相应目标。',tabs+body)}
function showSearchResults(company,keyword){const term=`${company} ${keyword}`.trim();ui.searchTerm=term;const matches=questions.filter(q=>(!company||q.meta.includes(company))&&(!keyword||keyword.split(/\s+/).some(k=>`${q.meta}${q.title}${q.category}${q.original}`.toLowerCase().includes(k.toLowerCase()))));$('#interview-results').innerHTML=`<hr class="divider"><div class="between"><h3>找到 ${matches.length} 条示例</h3><span class="small muted">内置示例库 · 非网络搜索</span></div>${matches.length?matches.map(q=>`<article class="search-result"><div class="source-meta"><span class="badge">${q.source}</span><span>${q.meta}</span></div><h3 class="mt8">${q.title}</h3><p>${q.original}</p><div class="search-result-footer"><span class="tag">${q.category}</span>${action('add-question','保存并适配我的项目','button sm',`data-index="${questions.indexOf(q)}"`)}</div></article>`).join(''):`<div class="empty-state mt16"><h3>示例库中没有匹配内容</h3><p>可尝试「澄川智能 / AI 产品」或「观澜数据 / 数据产品」。</p>${action('new-type','先创建准备目标','button','data-type="opportunity"')}</div>`}`}
function saveQuestionModal(index){ui.pendingQuestion=index;const q=questions[index];openModal('把这道题放进你的目标','原题保留；个人回答引用你已确认的项目事实。',`<div class="notice"><strong>${q.title}</strong><br>${q.source} · ${q.meta}</div><form id="save-question-form" class="mt16"><label for="question-target">保存到</label><select id="question-target">${state.opportunities.map(o=>`<option value="${o.id}" ${route().view==='opportunity'&&opp().id===o.id?'selected':''}>${esc(o.company)} · ${esc(o.role)}</option>`).join('')}<option value="new">新建公司 / 岗位准备目标…</option></select><div id="new-question-target" hidden class="form-grid mt16"><div><label for="question-company">公司</label><input id="question-company" value="${q.meta.split(' · ')[0]}"></div><div><label for="question-role">岗位</label><input id="question-role" value="${q.meta.split(' · ')[1]}"></div></div><label for="question-project" class="mt16">引用我的项目</label><select id="question-project"><option>${projectName()} · ${currentFacts().filter(f=>f.confirmed).length} 条已确认事实</option></select><p class="field-help">适配为本地预设演示，不虚构你的成果，不调用真实模型。</p><button class="button primary mt16" type="submit">保存问题并查看个人回答 ${icon('arrow','small-icon')}</button></form>`)}
function previewApplication(data){ui.formPreview=data;openModal('模拟填写预览','逐项核对后，再确认本机演示。',`<div class="notice amber">这是一张独立的模拟申请表，未连接任何招聘网站。</div>${[['姓名',data.name],['联系邮箱',data.email],['申请岗位',data.role],['项目经历',data.project]].map(([label,value])=>`<div class="review-field"><span>${label}</span><span>${esc(value)}</span><span class="badge">待确认</span></div>`).join('')}<form id="confirm-application-form" class="mt16"><label class="check-label"><input type="checkbox" required id="application-confirm"><span>我已逐项核对字段，确认这些内容可以用于本次模拟填写。</span></label><button class="button primary mt16" type="submit">确认模拟填写</button></form>`,action('close-modal','返回修改','button'))}
function editFact(id){const f=currentFacts().find(f=>f.id===id);openModal(`核对项目事实 · ${f.id}`,'请保留真实贡献、数字口径和未知结果。',`<form id="fact-form" data-id="${id}"><label for="fact-title">事实主题</label><input id="fact-title" name="title" value="${esc(f.title)}" required><label for="fact-text" class="mt16">事实内容</label><textarea id="fact-text" name="text" rows="6" required>${esc(f.text)}</textarea><label class="check-label mt16"><input name="confirmed" type="checkbox" ${f.confirmed?'checked':''}><span>我已核对这条表述的贡献范围与数字口径，确认可以用于个人表达。</span></label><p class="field-help">「确认」可包含明确的限制，例如“尚未验证线上结果”。</p><button class="button primary mt16" type="submit">保存到我的资料</button></form>`)}
function editAnswer(){const q=currentQuestion();const current=workspace().answers[ui.question]||q.answer.map(a=>a[1]).join('\n\n');openModal('编辑我的回答','修改保存在本机，不改变面经原文。',`<form id="answer-edit-form"><label for="answer-edit">${q.title}</label><textarea id="answer-edit" class="editable-answer" required>${esc(current)}</textarea><div class="notice mt12">请核对事实、数字与个人贡献。没有证据的效果，保留为下一步验证计划。</div><button type="submit" class="button primary mt16">保存个人回答</button></form>`)}
function bindForms(){const appForm=$('#application-form');if(appForm)appForm.onsubmit=e=>{e.preventDefault();previewApplication(Object.fromEntries(new FormData(appForm)))};const searchForm=$('#search-form');if(searchForm)searchForm.onsubmit=e=>{e.preventDefault();const d=new FormData(searchForm);showSearchResults(d.get('company').trim(),d.get('role').trim())};const createForm=$('#create-opportunity-form');if(createForm)createForm.onsubmit=e=>{e.preventDefault();const d=new FormData(createForm);if(!String(d.get('company')).trim()||!String(d.get('role')).trim()){toast('请填写公司与岗位名称。');return}const item=createOpportunity(d.get('company'),d.get('role'),d.get('jd'));closeModal();go(`opportunity/${item.id}/overview`);toast('已在本机创建目标机会；可以开始搜索面经。')};const chooseApp=$('#choose-application-form');if(chooseApp)chooseApp.onsubmit=e=>{e.preventDefault();const id=$('#application-opportunity').value;closeModal();go(`opportunity/${id}/application`)};const saveQ=$('#save-question-form');if(saveQ)saveQ.onsubmit=e=>{e.preventDefault();let id=$('#question-target').value;if(id==='new'){const c=$('#question-company').value.trim(),r=$('#question-role').value.trim();if(!c||!r){toast('请填写新目标的公司与岗位。');return}id=createOpportunity(c,r,'').id}ui.question=ui.pendingQuestion;if(!workspace(id).savedQuestions.includes(ui.question))workspace(id).savedQuestions.push(ui.question);persist();ui.answerTab='answer';ui.originalOpen=true;closeModal();go(`opportunity/${id}/interview`);toast('已保存示例原题，并展示基于项目事实的演示回答。')};const factForm=$('#fact-form');if(factForm)factForm.onsubmit=e=>{e.preventDefault();const d=new FormData(factForm),f=currentFacts().find(f=>f.id===factForm.dataset.id);f.title=String(d.get('title')).trim();f.text=String(d.get('text')).trim();f.confirmed=d.has('confirmed');persist();closeModal();render();toast('项目事实已保存在本机。')};const answerForm=$('#answer-edit-form');if(answerForm)answerForm.onsubmit=e=>{e.preventDefault();const v=$('#answer-edit').value.trim();workspace().answers[ui.question]=v;if(!workspace().savedQuestions.includes(ui.question))workspace().savedQuestions.push(ui.question);persist();closeModal();render();toast('个人回答已保存，面经原文保持独立。')};const confirmApp=$('#confirm-application-form');if(confirmApp)confirmApp.onsubmit=e=>{e.preventDefault();workspace().confirmedApplication=true;persist();openModal('模拟填写已确认','本次操作仅记录在本机。',`<div class="success-state"><div class="success-symbol">${icon('check')}</div><h3>字段已确认，演示完成</h3><p>4 项字段已写入模拟表单。<br>没有提交真实网申，也没有发送任何消息。</p></div>`,action('finish-application','返回机会','button primary'))};const review=$('#review-form');if(review)review.onsubmit=e=>{e.preventDefault();state.reviewComment=$('#review-comment').value;state.reviewPublished=true;persist();render();toast('已保存并演示发布点评；没有向学员发送消息。')};const profileForm=$('#profile-edit-form');if(profileForm)profileForm.onsubmit=e=>{e.preventDefault();state.profileDirection=$('#profile-direction').value.trim();persist();closeModal();render();toast('目标方向已在本机保存。')};const progressForm=$('#progress-form');if(progressForm)progressForm.onsubmit=e=>{e.preventDefault();const o=opp(),stage=$('#progress-stage').value,note=$('#progress-note').value.trim();o.stage=stage;state.stageHistory.push({id:o.id,stage,note});persist();closeModal();render();toast('进展已在本机记录。')};const editOpp=$('#edit-opportunity-form');if(editOpp)editOpp.onsubmit=e=>{e.preventDefault();Object.assign(opp(),{company:$('#edit-company').value.trim(),role:$('#edit-role').value.trim(),jd:$('#edit-jd').value.trim()});persist();closeModal();render();toast('目标机会已更新。')};const templateForm=$('#template-form');if(templateForm)templateForm.onsubmit=e=>{e.preventDefault();state.templates[templateForm.dataset.id]=$('#template-content').value;persist();closeModal();render();toast('服务模板已保存在本机。')}}
function createOpportunity(company,role,jd){const item={id:'custom-'+Date.now(),company:String(company).trim(),role:String(role).trim(),stage:'准备中',location:jd?'已添加岗位描述':'目标准备 · 尚未关联 JD',next:'自主安排 · 开始准备',action:'搜索相关面经，关联个人项目事实',materials:0,jd:String(jd||'').trim()};state.opportunities.push(item);persist();return item}
async function copyText(text){try{await navigator.clipboard.writeText(text);toast('招呼草稿已复制，请到招聘平台自行核对并发送。')}catch{const el=document.createElement('textarea');el.value=text;el.style.cssText='position:fixed;opacity:0;left:0;top:0';document.body.append(el);el.select();const success=document.execCommand('copy');el.remove();toast(success?'招呼草稿已复制，请自行核对后发送。':'本机限制复制，请选中招呼文本手动复制。')}}
function downloadMaterial(){const text=`OfferFlow · 示例资料导出\n\n${studentName()}｜产品方向\n目标：${opp().company} · ${opp().role}\n\n项目：${projectName()}\n${currentFacts().map(f=>`${f.id} ${f.title}（${f.confirmed?'已确认':'待确认'}）\n${f.text}`).join('\n\n')}\n\n交互原型 · 所有内容均为虚构示例，不作为真实求职材料。`;if(window.webkit?.messageHandlers?.careerAI){window.webkit.messageHandlers.careerAI.postMessage({action:'exportMaterial',filename:'CareerAI-示例项目材料.txt',text});return}const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));a.download='CareerAI-示例项目材料.txt';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000);toast('示例项目材料已导出为文本。')}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const name=b.dataset.action;switch(name){case'new-task':newTaskModal();break;case'create-opportunity':newTaskModal('opportunity');break;case'search-interviews':go('opportunities');break;case'new-type':newTaskModal(b.dataset.type);break;case'close-modal':closeModal();break;case'filter':ui.filter=b.dataset.filter;render();break;case'clear-filter':ui.filter='全部';ui.search='';render();break;case'toggle-task':state.tasksDone=state.tasksDone.includes(b.dataset.id)?state.tasksDone.filter(id=>id!==b.dataset.id):[...state.tasksDone,b.dataset.id];persist();render();toast(state.tasksDone.includes(b.dataset.id)?'已标记完成，可点击勾选撤销。':'已恢复为待办。');break;case'question':ui.question=Number(b.dataset.index);ui.originalOpen=false;ui.answerTab='answer';render();break;case'toggle-original':ui.originalOpen=!ui.originalOpen;render();break;case'answer-tab':ui.answerTab=b.dataset.tab;render();break;case'save-answer':if(!workspace().savedQuestions.includes(ui.question))workspace().savedQuestions.push(ui.question);persist();render();toast('演示回答已保存到该机会的准备材料。');break;case'edit-answer':editAnswer();break;case'practice-feedback':practice().text=$('#practice-answer').value.trim();if(!practice().text){toast('先输入你的回答，再查看示例反馈。');$('#practice-answer').focus();break}practice().feedback=true;persist();render();break;case'edit-fact':editFact(b.dataset.id);break;case'copy-greeting':copyText($('#greeting-text').textContent);break;case'download-material':downloadMaterial();break;case'preview-material':openModal('项目摘要 · 岗位表达版',`${esc(opp().company)} · ${esc(opp().role)} · 示例材料`,`<div class="quote-block">${esc(projectSummary())}<br><br>${esc(currentFacts()[3].text)}</div><div class="notice mt16">引用：F1 个人分工、F2 需求证据、F3 评估口径、F4 结果边界。请在真实使用前逐项核对。</div>`,action('download-material',icon('download','small-icon')+' 导出示例文本','button primary'));break;case'finish-application':closeModal();render();break;case'add-question':saveQuestionModal(Number(b.dataset.index));break;case'pricing':pricingModal();break;case'plan-interest':state.interestedPlan=b.dataset.plan;persist();$('#plan-status').innerHTML=`<div class="notice">已在本机记录：${esc(state.interestedPlan)}。没有提交信息或产生订阅。</div>`;break;case'save-review':state.reviewComment=$('#review-comment').value;persist();toast('点评草稿已在本机保存。');break;case'edit-profile':openModal('编辑基本资料','此处仅修改本机示例求职方向。',`<form id="profile-edit-form"><label for="profile-direction">目标方向</label><input id="profile-direction" value="${esc(state.profileDirection||'AI 产品经理 / 数据产品经理')}" required><button type="submit" class="button primary mt16">保存资料</button></form>`);break;case'update-progress':openModal('记录求职进展','这条记录会保存在当前机会的时间线。',`<form id="progress-form"><label for="progress-stage">当前阶段</label><select id="progress-stage">${['准备中','准备投递','已投递','面试中','已结束'].map(s=>`<option ${opp().stage===s?'selected':''}>${s}</option>`).join('')}</select><label for="progress-note" class="mt16">进展与下一步</label><textarea id="progress-note" required placeholder="记录发生了什么，以及接下来要做什么。"></textarea><button type="submit" class="button primary mt16">保存进展</button></form>`);break;case'show-jd':if(!opp().jd){document.dispatchEvent(new CustomEvent('edit-current-opportunity'));break}openModal('岗位描述','虚构示例 · 不代表真实招聘职位',`<h3>${esc(opp().company)} · ${esc(opp().role)}</h3><p class="mt16 medium" style="line-height:2;white-space:pre-line">${esc(opp().jd)}</p><div class="notice mt16">面经是补充信息，不替代岗位描述；同一公司、岗位不同轮次的要求可能不同。</div>`,action('edit-opportunity','编辑岗位描述','button'));break;case'edit-opportunity':editOpportunity();break;case'edit-template':openModal(`编辑模板 · ${esc(b.dataset.title)}`,'修改交付标准，保留每位学员的个性化判断。',`<form id="template-form" data-id="${b.dataset.id}"><label for="template-content">服务内容与交付标准</label><textarea id="template-content" rows="8" required>${esc(state.templates[b.dataset.id]||'第 1 步：核对项目事实与个人贡献。\n第 2 步：对齐目标岗位，明确需要的证据。\n第 3 步：完成一次材料批改并给出可执行建议。\n第 4 步：复核修改内容，记录下一步行动。\n\n交付标准：事实可追溯，建议具体，不承诺录用结果。')}</textarea><button class="button primary mt16" type="submit">保存模板到本机</button></form>`);break}});
function editOpportunity(){const o=opp();openModal('编辑目标机会','公司与岗位是准备的起点，JD 可以稍后补充。',`<form id="edit-opportunity-form"><div class="form-grid"><div><label for="edit-company">公司</label><input id="edit-company" value="${esc(o.company)}" required></div><div><label for="edit-role">岗位</label><input id="edit-role" value="${esc(o.role)}" required></div><div class="field-full"><label for="edit-jd">岗位描述（选填）</label><textarea id="edit-jd" rows="5">${esc(o.jd)}</textarea></div></div><button class="button primary mt16" type="submit">保存目标机会</button></form>`)}
document.addEventListener('edit-current-opportunity',editOpportunity);
document.addEventListener('input',e=>{if(e.target.id==='opportunity-search'){ui.search=e.target.value;$('#opportunity-list').innerHTML=opportunityRows()}if(e.target.id==='practice-answer'){practice().text=e.target.value;practice().feedback=false;$('#practice-count').textContent=`${practice().text.length} 字`;persist()}if(e.target.id==='review-comment'){state.reviewComment=e.target.value;persist()}});
document.addEventListener('change',e=>{if(e.target.id==='question-target'){$('#new-question-target').hidden=e.target.value!=='new'}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const box=$('#modal').getBoundingClientRect();if(e.clientX<box.left||e.clientX>box.right||e.clientY<box.top||e.clientY>box.bottom)closeModal()}});
window.addEventListener('hashchange',()=>{render();window.scrollTo({top:0});$('#main').focus({preventScroll:true})});

let chatSidebar={chats:[],selected:'',replying:[]};
window.offerFlowSidebarUpdate=data=>{
  chatSidebar=data;
  renderChatHistory();
};
function renderChatHistory(){
  const host=document.getElementById('chat-history');if(!host)return;
  const rows=chatSidebar.chats.map(chat=>{
    const active=chatSidebar.replying?.includes(chat.id);
    const current=route().view==='home' && chatSidebar.selected===chat.id;
    const label=esc(chat.title+(active?'，正在回答':''));
    const select=action('select-chat',`<span>${esc(chat.title)}</span>${active?'<i class="chat-running" aria-hidden="true"></i>':''}`,
      'chat-history-item'+(current?' is-current':''),`data-id="${esc(chat.id)}" title="${label}" aria-label="${label}"${current?' aria-current="page"':''}`);
    const remove=action('delete-chat',icon('trash'),'chat-delete',
      `data-id="${esc(chat.id)}" title="删除对话" aria-label="删除对话：${esc(chat.title)}"`);
    return `<div class="chat-history-row">${select}${remove}</div>`;
  });
  if(chatSidebar.hasMore) rows.push(action('more-chats','显示更早的对话','chat-history-item'));
  host.innerHTML=`<div class="workspace-section-label">最近对话</div><div class="chat-history-list">${rows.join('')||'<p class="chat-history-empty">你的对话会显示在这里</p>'}</div>`;
}
function renderSidebar(){
  const r=route(),current=['opportunity','opportunities'].includes(r.view)?'opportunities':r.view;
  const link=(href,ic,label)=>`<a class="workspace-nav-item ${current===href?'is-current':''}" href="#${href}" title="${label}" aria-label="${label}" ${current===href?'aria-current="page"':''}>${icon(ic)}<span>${label}</span>${current===href?'<span class="nav-current-mark" aria-hidden="true"></span>':''}</a>`;
  const sidebar=$('#sidebar');sidebar.classList.add('workspace-sidebar');applySidebarPreference();
  sidebar.innerHTML=`<div class="workspace-brand-row"><a class="workspace-brand" href="#home" aria-label="OfferFlow 首页"><span class="workspace-brand-mark"><img src="offerflow-icon.png" alt="" width="32" height="32"></span><span class="workspace-brand-copy">OfferFlow</span></a>${action('toggle-sidebar',icon('sidebar'),'sidebar-toggle',`title="${sidebarCollapsed?'展开侧边栏':'收起侧边栏'}" aria-label="${sidebarCollapsed?'展开侧边栏':'收起侧边栏'}" aria-expanded="${!sidebarCollapsed}"`)}</div>
  ${action('quick-search',`${icon('search')}<span>快速查找</span><kbd>⌘ K</kbd>`,'workspace-search','title="快速查找 ⌘K" aria-label="快速查找，Command K"')}
  <div class="sidebar-scroll"><div class="workspace-section-label">求职工作区</div><nav class="workspace-nav" aria-label="求职导航">${action('new-chat',`${icon('file')}<span>新对话</span>`,'workspace-nav-item','title="新对话" aria-label="新对话"')}${action('native-boss',`${icon('search')}<span>岗位发现</span><span class="nav-service-label">BOSS</span>`,'workspace-nav-item'+(['boss','saved'].includes(r.view)?' is-current':''),'title="岗位发现 · BOSS" aria-label="岗位发现，打开 BOSS 搜索"')}${link('liveJobs','grid','实时岗位库')}${link('applications','briefcase','投递管理')}${link('opportunities','practice','面经资料')}${link('coach','practice','面试陪练')}${link('calendar','grid','求职日历')}${link('mail','briefcase','求职邮箱')}</nav><section id="chat-history" class="chat-history" aria-label="最近对话"></section></div>
  <div class="workspace-footer">${action('native-account-menu',`${icon('person','account-avatar')}<span class="account-copy"><strong>个人工作空间</strong><small>本机账户</small></span>${icon('chevron','account-chevron')}`,'workspace-account','title="账户菜单" aria-label="账户菜单"')}</div>`;
  renderChatHistory();
}
function renderTopbar(){
  const r=route(),names={boss:'岗位发现 · BOSS',home:'新对话',opportunities:'面试准备',profile:'个人资料',applications:'投递管理',saved:'已保存岗位',liveJobs:'实时岗位库',resumes:'简历工作室',coach:'面试陪练',calendar:'求职日历',mail:'求职邮箱',matching:'岗位匹配',queue:'网申队列',knowledge:'资料库',tasks:'任务中心',offers:'Offer 对比',events:'重要事件'};
  let crumb=`<span>求职工作区</span><span class="breadcrumb-divider">/</span><b>${names[r.view]||'目标准备'}</b>`;
  if(r.view==='opportunity')crumb=`<a href="#opportunities">面试准备</a><span class="breadcrumb-divider">/</span><b>${esc(opp().company)}</b>`;
  $('#topbar').innerHTML=`<div class="breadcrumb">${crumb}</div><div class="workspace-top-actions">${!['home','applications','saved','liveJobs','profile','opportunities','resumes','coach','calendar','mail','matching','queue','knowledge','tasks','offers','events'].includes(r.view)?'<span class="workspace-preview">示例内容</span>'+action('new-task',icon('plus')+' 新建任务','button primary'):''}</div>`;
}
function render(){
  const allowed=['boss','home','opportunities','profile','applications','saved','liveJobs','coach','calendar','mail'];
  if(!allowed.includes(route().view))history.replaceState(null,'','#home');
  if(route().view==='opportunity'&&!state.opportunities.some(o=>o.id===route().id))history.replaceState(null,'','#home');
  const r=route();state.mode='personal';
  const active=document.activeElement;let focusSelector=active?.dataset?.action?`[data-action="${active.dataset.action}"]`:null;
  if(focusSelector)for(const key of ['id','index','tab','filter'])if(active.dataset[key])focusSelector+=`[data-${key}="${active.dataset[key]}"]`;
  renderSidebar();renderTopbar();
  const views={boss:nativeWorkspaceView,home:nativeWorkspaceView,resumes:nativeWorkspaceView,coach:nativeWorkspaceView,calendar:nativeWorkspaceView,mail:nativeWorkspaceView,matching:nativeWorkspaceView,queue:nativeWorkspaceView,knowledge:nativeWorkspaceView,tasks:nativeWorkspaceView,offers:nativeWorkspaceView,events:nativeWorkspaceView,opportunities:nativeWorkspaceView,opportunity:opportunityView,profile:nativeWorkspaceView,applications:nativeWorkspaceView,saved:nativeWorkspaceView,liveJobs:nativeWorkspaceView};
  $('#main').innerHTML=(views[r.view]||homeView)();document.title='求职工作区 · OfferFlow';bindForms();
  if(focusSelector)$(focusSelector)?.focus({preventScroll:true});syncNativeSurface();
}
function pricingModal(){
  openModal('会员与方案','当前使用本机工作空间，会员订阅与支付尚未开放。',`<div class="membership-status"><span class="membership-icon">${icon('person')}</span><div><strong>本机使用版本</strong><p>个人工作空间 · 当前设备保存</p></div><span class="settings-local">未开通订阅</span></div><div class="settings-section-title">当前可用</div><ul class="membership-features"><li><strong>BOSS 岗位发现与沟通</strong><span>使用真实岗位、简历与已配置模型生成招呼草稿</span></li><li><strong>岗位保存与投递管理</strong><span>查看岗位和匹配信息，记录求职进展</span></li><li><strong>求职资料设置</strong><span>在「AI 设置」中管理真实简历和模型连接</span></li></ul><div class="settings-storage"><strong>正在完善的功能</strong><p>岗位、面经、陪练、日历与邮箱连接本机资料；邮箱需配置你自己的服务，模型使用当前 API 设置。</p></div><p class="field-help mt16">当前没有订单或扣费。模型请求使用你配置的 API 连接；本页不展示或估算服务商账单。</p>`,action('close-modal','知道了','button primary'));
}
function nativeAction(actionName){const bridge=window.webkit?.messageHandlers?.careerAI;if(bridge?.postMessage){bridge.postMessage({action:actionName});return}openModal('请在 OfferFlow 桌面版使用','此入口连接桌面版现有的真实功能。',`<div class="notice">${actionName==='openBoss'?'BOSS 岗位搜索':actionName==='openSavedJobs'?'已保存岗位':actionName==='openApplications'?'投递管理':actionName==='openAccount'?'账号登录与注册':actionName==='openLiveJobs'?'实时岗位库':actionName==='openApplicationProfile'?'个人资料与网申档案':'AI 设置'}需要在 OfferFlow 桌面软件中打开。独立 HTML 原型不连接该功能，也不会模拟真实搜索结果。</div>`,action('close-modal','知道了','button primary'))}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;switch(b.dataset.action){case'toggle-sidebar':toggleSidebar();break;case'native-boss':go('boss');break;case'native-account':nativeAction('openAccount');break;case'native-account-menu':nativeAction('openAccountMenu');break;case'new-chat':nativeAction('newChat');break;case'delete-chat':nativeAction('deleteChat:'+b.dataset.id);break;case'more-chats':nativeAction('moreChats');break;case'select-chat':nativeAction('selectChat:'+b.dataset.id);break;case'native-saved':go('saved');break;case'native-settings':nativeAction('openAISettings');break}});

function syncNativeSurface(forceWorkspace=false){
  const bridge=window.webkit?.messageHandlers?.careerAI;
  if(!bridge)return;
  const view=route().view;
  const action=forceWorkspace||$('#modal').open?'suspendNativeSurface':(view==='opportunities'||(view==='opportunity'&&route().tab==='interview'))?'openInterviews':view==='applications'?'openApplications':view==='saved'?'openSavedJobs':view==='liveJobs'?'openLiveJobs':view==='profile'?'openApplicationProfile':({boss:'openBoss',home:'openHome',resumes:'openResumes',coach:'openCoach',calendar:'openCalendar',mail:'openMail',matching:'openMatching',queue:'openQueue',knowledge:'openKnowledge',tasks:'openTasks',offers:'openOffers',events:'openEvents'}[view]||'showWorkspace');
  bridge.postMessage({action});
}
function nativeWorkspaceView(){
  const applications=route().view==='applications',liveJobs=route().view==='liveJobs',profile=route().view==='profile',interviews=route().view==='opportunities';
  return `<section class="native-workspace-placeholder"><span class="native-workspace-icon">${icon(profile?'file':liveJobs?'grid':applications?'briefcase':'bookmark')}</span><h1>${interviews?'面经资料与个人练习':profile?'个人资料与网申档案':liveJobs?'实时岗位库':applications?'投递管理':'已保存岗位'}</h1><p>${window.webkit?.messageHandlers?.careerAI?'正在打开你的岗位工作区…':'在 OfferFlow 桌面软件中查看真实岗位与求职进展。'}</p><a href="#home" class="text-button">返回工作台 ${icon('arrow','small-icon')}</a></section>`;
}
function workspaceSettings(){
  openModal('账户与设置','管理本机工作空间及求职资料。',`<div class="settings-account"><span class="settings-avatar">${icon('person')}</span><div><strong>个人工作空间</strong><p>本机账户</p></div><span class="settings-local">本机保存</span></div>${action('native-account',`<span class="settings-row-icon">${icon('person')}</span><span class="settings-row-copy"><strong>登录或注册账号</strong><small>账号密码与微信登录入口</small></span>${icon('chevron')}`,'settings-row')}<div class="settings-section-title">求职设置</div>${action('native-settings',`<span class="settings-row-icon">${icon('file')}</span><span class="settings-row-copy"><strong>AI 设置</strong><small>管理真实简历、模型连接与生成配置</small></span>${icon('chevron')}`,'settings-row')}<div class="settings-section-title">会员与数据</div>${action('pricing',`<span class="settings-row-icon">${icon('plan')}</span><span class="settings-row-copy"><strong>会员与方案</strong><small>查看当前版本与可用功能</small></span>${icon('chevron')}`,'settings-row')}<div class="settings-storage"><strong>工作空间资料</strong><p>原岗位与草稿继续保存在本机。简历、面经、任务、邮件与网申档案保存在本机；模型生成使用你配置的 AI 服务。</p></div><div class="settings-app-info"><strong>OfferFlow</strong><span>0.13.1（41）· macOS 桌面版</span></div>`,action('close-modal','完成','button primary'));
}
